export function due(lastShot: Date, months: number): Date {
  const d = new Date(lastShot);
  d.setMonth(d.getMonth() + months);
  return d;
}

export function dayBefore(at: Date): Date {
  return new Date(at.getTime() - 86_400_000);
}

